import test from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { signatureDigest, SignatureMode } from "../src/index.js";
import type { SighashContext, SigHashType } from "../src/index.js";

interface Vector {
  name: string;
  rawTransaction: string;
  inputIndex: number;
  mode: "legacy" | "bip143";
  scriptCode: string;
  prevOutValue: string;
  sigHashType: number;
  lastCodeSeparatorOffset: number | null;
  expected: string;
}

// Known-answer vectors generated by the independent Python reference
// implementation in test/gen_vectors.py.
const vectors = JSON.parse(
  readFileSync(new URL("../../test/vectors.json", import.meta.url), "utf8"),
) as Vector[];

for (const vector of vectors) {
  test(`vector: ${vector.name}`, () => {
    const context: SighashContext = {
      rawTransaction: Buffer.from(vector.rawTransaction, "hex"),
      inputIndex: vector.inputIndex,
      mode:
        vector.mode === "legacy" ? SignatureMode.Legacy : SignatureMode.Bip143,
      scriptCode: Buffer.from(vector.scriptCode, "hex"),
      prevOutValue: BigInt(vector.prevOutValue),
      sigHashType: vector.sigHashType as SigHashType,
      lastCodeSeparatorOffset: vector.lastCodeSeparatorOffset,
    };
    const digest = signatureDigest(context);
    assert.equal(digest.toString("hex"), vector.expected);
  });
}
